// tar_ref_smoke — archive/tar's reader against a running Go.
// (archive/tar/reader.go, archive/tar/common.go)
//
// Every expectation below is what a real Go 1.25.5 prints: the lines in
// GO are the verbatim output of `tools/gen_tar_ref.go` run in
// `package tar_test` by `scripts/goref.sh`. The ARCHIVE BYTES come from
// that same run and are embedded here as hex, so both sides parse the
// SAME input — building them with goish's own writer would let a writer
// bug mask a reader bug, which is the mistake this smoke is shaped to
// avoid.
//
// archive/tar reads archives that arrived from somewhere else, and tar
// has a long history of the two failure modes that matter: a header
// that says one thing while the body is another, and a Name that
// escapes the directory it is supposed to land in.
//
// goish matched Go on all 30 lines. What is pinned:
//
//   * A traversing Name ("../../etc/passwd") and an absolute one
//     ("/etc/shadow") are returned VERBATIM. That is Go's contract —
//     the reader does not sanitise, the caller must — and pinning it is
//     the point: a port that silently cleaned the Name would hide the
//     hazard from callers who currently have to handle it, and a caller
//     who believed it was clean would stop checking. Compare
//     mime/multipart's FileName in 4a95306, which Go DOES base-name,
//     citing RFC 7578: the two packages differ deliberately, and only a
//     reference tells you which is which.
//   * A Name longer than 100 bytes is reassembled from USTAR's prefix
//     or a PAX record — a truncated Name is how one tool writes a path
//     another cannot find.
//   * A header whose CHECKSUM does not match is refused rather than
//     used, and so is a size field that is not octal.
//   * A truncated header, a body shorter than the declared Size, and a
//     Size larger than the archive each produce their own error rather
//     than a silent short read.
//   * An all-zero block is a valid EMPTY archive, and empty input is
//     EOF at once.
//   * Uid/Gid/Uname/Gname, the type flags for regular files,
//     directories and symlinks, and a size past 8GiB all survive the
//     round trip.

#![no_std]
#![no_main]
#![allow(non_snake_case)]

extern crate alloc;
extern crate goish;

use alloc::boxed::Box;
use goish::archive::tar;
use goish::bytes;
use goish::fmt;
use goish::goslice::slice;
use goish::gostring::string;
use goish::io;
use goish::syscall;
use goish::types::{byte, int, rune};

fn s(x: &str) -> string {
    return string::from_bytes(x.as_bytes());
}
fn unhex(h: &str) -> alloc::vec::Vec<u8> {
    let b = h.as_bytes();
    let mut out: alloc::vec::Vec<u8> = alloc::vec::Vec::with_capacity(b.len() / 2);
    let mut i = 0usize;
    while i + 1 < b.len() {
        let hi = (b[i] as char).to_digit(16).unwrap_or(0) as u8;
        let lo = (b[i + 1] as char).to_digit(16).unwrap_or(0) as u8;
        out.push((hi << 4) | lo);
        i += 2;
    }
    return out;
}

// The archive bytes come from the Go generator, so both sides parse the
// SAME input; building them with goish's own writer would let a writer
// bug mask a reader bug.
const ARCHIVES: [(&str, &str); 17] = [
    ("simple", ""),
    ("two-files", ""),
    ("empty-file", ""),
    ("dir", ""),
    ("symlink", ""),
    ("long-name", ""),
    ("traversal", ""),
    ("abs-path", ""),
    ("uid-gid", ""),
    ("big-size", ""),
    ("pax-times", ""),
    ("bad-checksum", ""),
    ("truncated-hdr", ""),
    ("short-body", ""),
    ("only-eof", ""),
    ("empty", ""),
    ("bad-size", ""),
];

// go: none — goish idiom: the reference lines, in the order Go printed
//     them. Comparing whole rendered lines keeps this smoke and the
//     generator in lockstep: a case added to one is a mismatch in the
//     other, never a silent pass.
const GO: [&str; 30] = [
    "parse simple        #0 -> name=\"a.txt\" type=\"0\" size=5 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"hello\" rerr=<nil>",
    "parse simple        #1 -> EOF",
    "parse two-files     #0 -> name=\"a\" type=\"0\" size=1 mode=600 uid=0 gid=0 uname=\"\" link=\"\" body=\"x\" rerr=<nil>",
    "parse two-files     #1 -> name=\"b\" type=\"0\" size=3 mode=755 uid=0 gid=0 uname=\"\" link=\"\" body=\"yyy\" rerr=<nil>",
    "parse two-files     #2 -> EOF",
    "parse empty-file    #0 -> name=\"empty\" type=\"0\" size=0 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"\" rerr=<nil>",
    "parse empty-file    #1 -> EOF",
    "parse dir           #0 -> name=\"d/\" type=\"5\" size=0 mode=755 uid=0 gid=0 uname=\"\" link=\"\" body=\"\" rerr=<nil>",
    "parse dir           #1 -> EOF",
    "parse symlink       #0 -> name=\"l\" type=\"2\" size=0 mode=777 uid=0 gid=0 uname=\"\" link=\"target\" body=\"\" rerr=<nil>",
    "parse symlink       #1 -> EOF",
    "parse long-name     #0 -> name=\"d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/d/f.txt\" type=\"0\" size=2 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"hi\" rerr=<nil>",
    "parse long-name     #1 -> EOF",
    "parse traversal     #0 -> name=\"../../etc/passwd\" type=\"0\" size=3 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"bad\" rerr=<nil>",
    "parse traversal     #1 -> EOF",
    "parse abs-path      #0 -> name=\"/etc/shadow\" type=\"0\" size=1 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"z\" rerr=<nil>",
    "parse abs-path      #1 -> EOF",
    "parse uid-gid       #0 -> name=\"u\" type=\"0\" size=0 mode=644 uid=1234 gid=5678 uname=\"alice\" link=\"\" body=\"\" rerr=<nil>",
    "parse uid-gid       #1 -> EOF",
    "parse big-size      #0 -> name=\"big\" type=\"0\" size=8589934592 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"\" rerr=unexpected EOF",
    "parse big-size      #1 -> err=\"unexpected EOF\"",
    "parse pax-times     #0 -> name=\"p\" type=\"0\" size=0 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"\" rerr=<nil>",
    "parse pax-times     #1 -> EOF",
    "parse bad-checksum  #0 -> err=\"archive/tar: invalid tar header\"",
    "parse truncated-hdr #0 -> err=\"unexpected EOF\"",
    "parse short-body    #0 -> name=\"short\" type=\"0\" size=100 mode=644 uid=0 gid=0 uname=\"\" link=\"\" body=\"abc\" rerr=unexpected EOF",
    "parse short-body    #1 -> err=\"unexpected EOF\"",
    "parse only-eof      #0 -> EOF",
    "parse empty         #0 -> EOF",
    "parse bad-size      #0 -> err=\"archive/tar: invalid tar header\"",
];

// go: none — goish idiom: one comparison, printing the divergence when
//     it is one, so a FAIL says what it got and not just that it did.
fn chk(failed: &mut int, ln: &mut int, got: string) {
    if *ln >= GO.len() as int {
        fmt::Printf!("[!!] extra line %d: %q\n", *ln + 1, got);
        *failed += 1;
        *ln += 1;
        return;
    }
    let want = s(GO[*ln as usize]);
    *ln += 1;
    if got == want {
        return;
    }
    fmt::Printf!("[!!] line %d FAIL\n  got  %q\n  want %q\n", *ln, got, want);
    *failed += 1;
}

#[goish::main]
fn main() {
    let mut failed: int = 0;
    let mut ln: int = 0;

    for (name, hexs) in ARCHIVES.iter() {
        let data = unhex(hexs);
        let src = bytes::NewReader(slice::__from_vec(data));
        let mut r = tar::NewReader(Box::new(src));
        for i in 0..5i64 {
            let (h, err) = r.Next();
            if !err.IsNil() {
                if err.Error() == s("EOF") {
                    chk(
                        &mut failed,
                        &mut ln,
                        fmt::Sprintf!("parse %-13s #%d -> EOF", s(name), i),
                    );
                } else {
                    chk(
                        &mut failed,
                        &mut ln,
                        fmt::Sprintf!("parse %-13s #%d -> err=%q", s(name), i, err.Error()),
                    );
                }
                break;
            }
            let (body, rerr) = io::ReadAll(&mut r);
            let re = if rerr.IsNil() {
                s("<nil>")
            } else {
                rerr.Error()
            };
            chk(&mut failed, &mut ln, fmt::Sprintf!(
                "parse %-13s #%d -> name=%q type=%q size=%d mode=%o uid=%d gid=%d uname=%q link=%q body=%q rerr=%s",
                s(name), i, h.Name.clone(), string::from_bytes(&[h.Typeflag]), h.Size, h.Mode,
                h.Uid, h.Gid, h.Uname.clone(), h.Linkname.clone(), body, re
            ));
        }
    }
    let _: byte = 0;
    let _: int = 0;
    if ln != GO.len() as int {
        fmt::Printf!("[!!] produced %d lines, pinned %d\n", ln, GO.len() as int);
        failed += 1;
    }
    if failed == 0 {
        fmt::Printf!("ok %d/%d\n", ln, ln);
        return;
    }
    fmt::Printf!("FAILED %d of %d\n", failed, ln);
    syscall::Exit(1);
}
